{"action": "write", "project": {"project_name": "Agent Counter", "summary": "A simple offline browser application with a heading, a count starting at 0, an Add button to increase the count, and a Reset button to restore the count to zero. The application has a dark background with readable text.", "entrypoint": "index.html", "files": [{"path": "index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Agent Counter</title>
  <style>
    body {
      background-color: #333;
      color: #fff;
      font-family: Arial, sans-serif;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      height: 100vh;
      margin: 0;
    }
    h1 {
      margin-bottom: 20px;
    }
    button {
      margin: 5px;
      padding: 10px 20px;
      font-size: 16px;
      cursor: pointer;
    }
  </style>
</head>
<body>
  <h1>Agent Counter</h1>
  <h2 id="count">0</h2>
  <button id="add">Add</button>
  <button id="reset">Reset</button>

  <script>
    let count = 0;

    document.getElementById('add').addEventListener('click', () => {
      count += 1;
      document.getElementById('count').textContent = count;
    });

    document.getElementById('reset').addEventListener('click', () => {
      count = 0;
      document.getElementById('count').textContent = count;
    });
  </script>
</body>
</html>"}]}}

